// Extract incoming JSON body
const body = $json.body;
const base64Data = body.fileData;
const fileName = body.fileName || 'whatsapp_call.webm';
const mimeType = body.mimeType || 'audio/webm';

// Convert Base64 string to Binary Buffer
const buffer = Buffer.from(base64Data, 'base64');

// Generate clean transcript filename
const transcriptFileName = fileName.replace(/\.[^/.]+$/, "") + "_transcript.txt";

return [{
  json: {
    fileName: fileName,
    transcriptFileName: transcriptFileName,
    audioDriveFileId: body.driveFileId,
    audioDriveFileUrl: body.driveFileUrl
  },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: mimeType,
      fileName: fileName
    }
  }
}];

